UPDATE companies SET description = 'Поставщик предлагает различные виды упаковочных материалов со склада в Москве. В наличии представлены бумажные и пластиковые пакеты, включая варианты с zip-lock, а также воздушно-пузырчатая плёнка, наполнители и паллеты. Компания также осуществляет полиграфические услуги, фасовку и упаковку товаров.', updated_at = now() WHERE slug = 'andipack';
UPDATE companies SET description = 'В наличии на складе в Москве представлены различные виды пакетов, включая бумажные, пластиковые, полиэтиленовые и варианты с zip-lock для удобного многократного использования. Также компания Abcpack поставляет воздушно-пузырчатую плёнку, картонную упаковку и наполнители для надёжной защиты товаров при транспортировке. Для крупных грузов доступны паллеты и упаковка из гофрированного картона (ВПП).', updated_at = now() WHERE slug = 'abcpack';
UPDATE companies SET description = 'В наличии представлена продукция для различных упаковочных задач: от пакетов из ВПП и воздушно-пузырчатой плёнки до картонной упаковки и европоддонов. Компания «579» поставляет бумажные и полиэтиленовые пакеты, включая модели с zip-lock, а также упаковочный скотч и наполнители. Ассортимент включает и профессиональное оборудование для упаковки, а также средства индивидуальной защиты.', updated_at = now() WHERE slug = '579';
UPDATE companies SET description = 'Предприятие находится в Новой Москве и предлагает широкий спектр упаковочных материалов и оборудования. В ассортименте представлены стрейч-плёнка, упаковочный скотч, полиэтиленовые пакеты, а также паллеты и европоддоны. Для автоматизации процессов доступно фасовочно-упаковочное и упаковочное оборудование. Также компания занимается производством и реализацией подарочной упаковки и складского оснащения.', updated_at = now() WHERE slug = '2rask';
UPDATE companies SET description = 'В ассортименте компании Anpack из Москвы представлены различные виды защитных и упаковочных материалов. Поставщик предлагает воздушно-пузырчатую и стрейч-плёнку, упаковочный скотч и клейкую ленту. Для фасовки доступны полиэтиленовые и бумажные пакеты, в том числе с замком zip-lock, а также изделия из ВПП. В наличии также имеются картонная и подарочная упаковка, а также различные наполнители.', updated_at = now() WHERE slug = 'anpack';
UPDATE companies SET description = 'В наличии представлен ассортимент упаковочных материалов: стрейч-плёнка, различные виды скотча, а также полиэтиленовые пакеты. Компания также предлагает европоддоны и паллеты для организации складской логистики и перевозки грузов. Для упаковки товаров в розничной продаже доступна подарочная упаковка и картонная тара. Расположение поставщика в Москве обеспечивает удобную логистику для столичных покупателей.', updated_at = now() WHERE slug = 'armorcases';
UPDATE companies SET description = 'Компания реализует разнообразные упаковочные решения со склада в Москве. В ассортименте представлены пластиковая тара, паллеты и европоддоны для логистики. Для розничной упаковки доступны полиэтиленовые и подарочные пакеты, а также изделия из ВПП и воздушно-пузырчатая плёнка. Также в наличии имеются различные виды клейкой ленты и упаковочного скотча для фиксации грузов.', updated_at = now() WHERE slug = 'b2btara';
UPDATE companies SET description = 'Компания из Москвы, расположенная в промзоне на Сигнальном проезде, специализируется на поставках товаров для организации систем полива и водоснабжения. В ассортименте представлены шланги для различных нужд, включая садовые и напорные, а также соединительная арматура, капельные ленты, фитинги и контроллеры для автоматического полива. Поставщик предлагает продукцию для монтажа и обслуживания как простых дачных систем, так и более сложных решений для приусадебных участков и тепличных хозяйств.', updated_at = now() WHERE slug = 'allforwater';
UPDATE companies SET description = 'В компании можно подобрать необходимую упаковку для различных товаров: от бумажных и полиэтиленовых пакетов до защитных материалов, таких как воздушно-пузырчатая и стрейч-плёнка. В ассортименте представлены подарочные варианты, а также функциональные решения с zip-застёжкой. Поставщик работает с юридическими лицами и предлагает широкий выбор клейких лент, наполнителей и картонной упаковки. Продукция находится в Москве на Новоалексеевской улице.', updated_at = now() WHERE slug = 'asd';
UPDATE companies SET description = 'Изготовление упаковочного скотча с фирменным логотипом позволяет усилить узнаваемость бренда. Компания из Москвы предлагает полный цикл полиграфических услуг — от препресса до послепечатной обработки, включая возможности швейного производства. Производственный комплекс расположен на улице Сущёвский Вал и специализируется на создании персонализированной упаковочной продукции. Это даёт возможность заказчикам получить готовые решения для промоакций или логистических нужд.', updated_at = now() WHERE slug = 'bag-pack';
UPDATE companies SET description = 'Поставщик из Москвы предлагает широкий спектр упаковочных материалов на складе на 16-й Парковой улице. В наличии представлена как продукция для транспортировки: европоддоны, паллеты, картонная упаковка, стрейч- и воздушно-пузырчатая плёнка, так и потребительские товары. Компания реализует различные типы пакетов, включая пластиковые, полиэтиленовые и из ВПП, а также подарочную упаковку и упаковочный скотч. Ассортимент позволяет обеспечить полный цикл упаковки товаров для бизнеса.', updated_at = now() WHERE slug = 'bbkey';
UPDATE companies SET description = 'Заказчикам в Москве и ближайших районах доступен широкий ассортимент упаковочных решений от производителя Best Box. В каталоге представлены бумажные и полиэтиленовые пакеты, включая варианты с zip-lock, а также воздушно-пузырчатая пленка, упаковочный скотч и различные наполнители. Предприятие располагает собственными производственными мощностями, что позволяет выполнять нанесение логотипов, плоттерную резку и оказывать полный цикл полиграфических услуг от препресса до послепечатной обработки. Для сложных задач доступны онлайн-консультации специалистов компании.', updated_at = now() WHERE slug = 'best-box';
